// Actual protected Engine/SQLite transitions with synthetic immutable native audit rows.
struct GroupedFixture(SyntheticAdapter);
#[async_trait]
impl Adapter for GroupedFixture {
    fn definitions(&self)->Vec<Definition>{self.0.definitions()}
    async fn read(&self,o:&str,i:&Value)->Result<Value>{self.0.read(o,i).await}
    async fn prepare(&self,o:&str,i:&Value)->Result<PreparedOperation>{let mut p=self.0.prepare(o,i).await?;p.binding["orders"]=json!([{"size":"1"},{"size":"1"}]);Ok(p)}
    async fn revalidate(&self,p:&PreparedOperation)->Result<PreparedOperation>{Ok(p.clone())}
    async fn submit(&self,p:&PreparedOperation,j:Arc<dyn SubmissionJournal>)->Result<Submission>{self.0.submit(p,j).await}
    async fn reconcile(&self,r:&OperationRecord)->Result<Reconciliation>{self.0.reconcile(r).await}
}
fn grouped_prepared(original:&OperationRecord,second_increase:bool)->PreparedOperation {
    use gofin_domain::grouped_amendments::*;
    let original_scope=gofin_domain::amendments::AmendmentScope{intent:original.preview.as_ref().unwrap().intent.clone(),binding:original.preview.as_ref().unwrap().binding.clone(),valuation:original.preview.as_ref().unwrap().valuation.clone()};
    let mut children=Vec::new();
    for (i,n,movement) in [(0,"2000000000000000000","2000000"),(1,if second_increase{"2000000000000000000"}else{"500000000000000000"},if second_increase{"2000000"}else{"500000"})]{
        let p=synthetic_amendment(original,n,movement,if i==0||second_increase{"1000000000000000000"}else{"0"});let EffectConstraint::SubmissionAmendment{mut revision,..}=p.intent.expected[0].clone()else{unreachable!()};revision.binding=original_scope.binding.clone();let size=if i==0||second_increase{"2"}else{"0.5"};revision.binding["orders"][i]["size"]=json!(size);
        children.push(GroupedAmendmentChild{child_tag:format!("member-{i}"),mutation:GroupedChildMutation::Amend,scope:revision,binding_replacements:vec![BindingReplacement{pointer:format!("/orders/{i}/size"),before:json!("1"),after:json!(size)}]});
    }
    let mut group=GroupedAmendmentGroup{operation_id:original.id.clone(),submission:original.submission.clone().unwrap(),original_scope:Box::new(original_scope.clone()),shared_binding_replacements:vec![],children,approved_envelope:Box::new(original_scope.clone()),incremental_valuation:None};
    let mut envelope=original_scope.clone();let total=if second_increase{"3000000000000000000"}else{"2000000000000000000"};envelope.intent.debits[0].amount.atoms=quantity(total);if let EffectConstraint::Transfer{maximum_debit,..}=&mut envelope.intent.expected[0]{*maximum_debit=quantity(total);}
    envelope.binding=compose_binding(&group,group.children.iter().map(|c|c.child_tag.as_str())).unwrap();envelope.valuation.as_mut().unwrap().movement_usd_micros=quantity(if second_increase{"3000000"}else{"2000000"});group.approved_envelope=Box::new(envelope);
    let mut incremental=original_scope.valuation.clone().unwrap();incremental.movement_usd_micros=quantity(if second_increase{"2000000"}else{"1000000"});group.incremental_valuation=Some(incremental);
    let mut p=original.preview.clone().unwrap();p.input=json!({"amendments":group.children.iter().map(|c|json!({"orderTag":c.child_tag,"operationId":original.id,"originalSubmission":original.submission})).collect::<Vec<_>>()});p.intent.debits[0].amount.atoms=quantity(if second_increase{"2000000000000000000"}else{"1000000000000000000"});p.intent.maximum_costs.clear();p.intent.expected=vec![EffectConstraint::GroupedSubmissionAmendments{group:Box::new(group)}];p.valuation.as_mut().unwrap().movement_usd_micros=quantity(if second_increase{"2000000"}else{"1000000"});p.binding=json!({"syntheticGrouped":true});p
}
fn grouped_receipt(record:&OperationRecord,children:Vec<gofin_domain::compound_mutations::MutationChildProof>)->VerifiedEffects{
    let EffectConstraint::GroupedSubmissionAmendments{group}=&record.preview.as_ref().unwrap().intent.expected[0]else{unreachable!()};
    let proof=gofin_domain::grouped_amendments::GroupedAmendmentProof{operation_id:group.operation_id.clone(),submission:group.submission.clone(),children};
    let events=proof.children.iter().map(|c|json!({"eventId":format!("synthetic-member:{}",c.child_tag),"native":c})).collect::<Vec<_>>();let mut v=VerifiedEffects{evidence_version:1,submission:record.submission.clone().unwrap(),effects:vec![FinancialEffect::GroupedSubmissionAmendments{proof}],evidence:json!({"proofEvents":events}),observed_at:now(),proof_digest:String::new()};v.proof_digest=verified_effect_digest(&v).unwrap();v
}
#[tokio::test]
async fn grouped_same_owner_does_not_net_decrease_against_increase_or_duplicate_shared_fees(){
    let d=tempfile::tempdir().unwrap();let e=synthetic_engine(&d.path().join("grouped.sqlite"),Arc::new(GroupedFixture(SyntheticAdapter::new())));let o=e.execute(OperationRequest{request_id:"synthetic-group-owner".into(),operation:"synthetic.transfer".into(),input:json!({}),run_id:None}).await.unwrap();
    let p=grouped_prepared(&o,false);e.validate_submission_amendment(&p,None,false).unwrap();assert!(e.validate_submission_amendment(&p,None,true).is_err());assert!(e.validate_submission_amendment(&p,Some("run"),false).is_err());
    let EffectConstraint::GroupedSubmissionAmendments{group}=&p.intent.expected[0]else{unreachable!()};let scope=grouped_amendments::accounting_scope(group,&group.children.iter().map(|c|c.child_tag.clone()).collect()).unwrap();assert_eq!(scope.intent.debits[0].amount.atoms.to_string(),"2000000000000000000");
    let mut missing_valuation=p.clone();if let EffectConstraint::GroupedSubmissionAmendments{group}=&mut missing_valuation.intent.expected[0]{group.incremental_valuation=None;}assert!(e.validate_submission_amendment(&missing_valuation,None,false).is_err(),"new grouped financial authority cannot omit independently priced positive increments");
    let mut bad=p.clone();bad.intent.debits[0].amount.atoms=quantity("500000000000000000");assert!(e.validate_submission_amendment(&bad,None,false).is_err());
    let mut g=(**group).clone();let fee=CostBound{location:AccountingLocation::Cash{resource:resource("binance-account")},amount:Amount{asset:asset("binance","ETH",18),atoms:quantity("3")},treatment:CostTreatment::AdditionalDebit};g.original_scope.intent.maximum_costs=vec![CostBound{amount:Amount{atoms:quantity("1"),..fee.amount.clone()},..fee.clone()}];for c in &mut g.children{c.scope.intent.maximum_costs=vec![fee.clone()];}
    assert_eq!(grouped_amendments::accounting_scope(&g,&g.children.iter().map(|c|c.child_tag.clone()).collect()).unwrap().intent.maximum_costs[0].amount.atoms.to_string(),"3","global fee ceiling is counted once");g.children[1].scope.intent.maximum_costs[0].amount.atoms=quantity("4");assert!(grouped_amendments::accounting_scope(&g,&g.children.iter().map(|c|c.child_tag.clone()).collect()).is_err());
}
#[tokio::test]
async fn grouped_partial_acceptance_restart_rejection_preserves_one_fill_owner_and_exact_reserves(){
    use gofin_domain::compound_mutations::{MutationChildProof,ChildMutationOutcome};
    let d=tempfile::tempdir().unwrap();let path=d.path().join("grouped-progress.sqlite");let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let original=e.execute(OperationRequest{request_id:"synthetic-group-original".into(),operation:"synthetic.transfer".into(),input:json!({}),run_id:None}).await.unwrap();let prepared=grouped_prepared(&original,true);e.validate_submission_amendment(&prepared,None,false).unwrap();
    let mut mutation=original.clone();mutation.id="synthetic-group-mutation".into();mutation.request_id=mutation.id.clone();mutation.fingerprint=mutation.id.clone();mutation.input=prepared.input.clone();mutation.preview=Some(prepared.clone());mutation.status=Status::AwaitingApproval;mutation.submission=None;mutation.effects=None;mutation.last_reconciliation_evidence=None;mutation.approval.as_mut().unwrap().binding_hash=binding_hash(&authorization_binding(&prepared)).unwrap();e.store.lock().unwrap().create_request(&mutation.id,&mutation.request_id,&mutation.fingerprint,&mutation.operation,None,"awaiting_approval",&to_value(&mutation).unwrap(),&now()).unwrap();e.reserve_ordinary_operation(&mut mutation,&prepared, None, None).unwrap();
    let dispatch=Submission{kind:"synthetic_tx".into(),reference:"synthetic-group-dispatch".into(),data:json!({"native":"synthetic-only"})};e.store.lock().unwrap().persist_submission(&mutation.id,&SubmissionRow{kind:dispatch.kind.clone(),reference:dispatch.reference.clone(),data:dispatch.data.clone()},&now()).unwrap();mutation=e.load_record(&mutation.id).unwrap();
    let EffectConstraint::GroupedSubmissionAmendments{group}=&prepared.intent.expected[0]else{unreachable!()};
    let first=MutationChildProof{child_tag:"member-0".into(),operation_id:original.id.clone(),submission:original.submission.clone().unwrap(),outcome:ChildMutationOutcome::Accepted{successor:None},native_evidence:json!({"bindingReplacementDigest":binding_hash(&to_value(&group.children[0].binding_replacements).unwrap()).unwrap(),"nativeAudit":{"auditId":"synthetic-audit-a"},"nativeReadback":{"size":"2"}})};
    let v=grouped_receipt(&mutation,vec![first.clone()]);let partial=e.apply_reconciliation(mutation,Reconciliation{status:Status::Pending,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();let revisions=e.amendment_context(&original.id).unwrap().revisions;assert_eq!(revisions.len(),1);assert_eq!(revisions[0].scope.binding["orders"][1]["size"],"1");assert_eq!(e.load_record(&original.id).unwrap(),original);assert!(e.has_pending_amendment(&original.id).unwrap());
    let held=e.store.lock().unwrap().operation_reservations(&partial.id).unwrap();assert!(held.iter().any(|r|r.units=="1000000000000000000"),"only the uncertain member's positive principal stays reserved");
    drop(e);let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let restored=e.load_record(&partial.id).unwrap();let mut conflict=first.clone();conflict.native_evidence["nativeReadback"]["size"]=json!("3");let v=grouped_receipt(&restored,vec![conflict]);assert!(e.apply_reconciliation(restored.clone(),Reconciliation{status:Status::Pending,evidence:v.evidence.clone(),verified:Some(v)}).is_err());
    let v=grouped_receipt(&restored,vec![first.clone()]);let duplicate=e.apply_reconciliation(restored,Reconciliation{status:Status::Pending,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert_eq!(e.amendment_context(&original.id).unwrap().revisions.len(),1);
    let rejected=MutationChildProof{child_tag:"member-1".into(),operation_id:original.id.clone(),submission:original.submission.clone().unwrap(),outcome:ChildMutationOutcome::Rejected{code:"INSUFFICIENT_FUNDS".into()},native_evidence:json!({"nativeError":"synthetic rejected b"})};let v=grouped_receipt(&duplicate,vec![first,rejected]);let final_record=e.apply_reconciliation(duplicate,Reconciliation{status:Status::Failed,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert_eq!(e.store.lock().unwrap().reservation_count(&final_record.id).unwrap(),0);assert_eq!(e.load_record(&original.id).unwrap(),original);assert_eq!(e.amendment_context(&original.id).unwrap().revisions.last().unwrap().scope.binding["orders"][1]["size"],"1");assert!(!e.has_pending_amendment(&original.id).unwrap());
}

#[tokio::test]
async fn grouped_accepted_cancel_cannot_activate_unknown_amendment_authority_or_shared_fees(){
    use gofin_domain::{grouped_amendments::GroupedChildMutation,compound_mutations::{MutationChildProof,ChildMutationOutcome}};
    let d=tempfile::tempdir().unwrap();let path=d.path().join("grouped-cancel.sqlite");let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let original=e.execute(OperationRequest{request_id:"synthetic-group-cancel-original".into(),operation:"synthetic.transfer".into(),input:json!({}),run_id:None}).await.unwrap();let mut prepared=grouped_prepared(&original,false);
    let EffectConstraint::GroupedSubmissionAmendments{group}=&mut prepared.intent.expected[0]else{unreachable!()};group.children[1].mutation=GroupedChildMutation::Cancel;group.children[1].binding_replacements.clear();group.children[1].scope=group.original_scope.clone();*group.approved_envelope=gofin_domain::grouped_amendments::derive_accounting_scope(group,&group.children.iter().map(|c|c.child_tag.clone()).collect()).unwrap();
    let group=(**group).clone();
    e.validate_submission_amendment(&prepared,None,false).unwrap();
    let accepted=std::collections::BTreeSet::from(["member-1".into()]);assert_eq!(gofin_domain::grouped_amendments::derive_accounting_scope(&group,&accepted).unwrap(),*group.original_scope);assert_eq!(gofin_domain::grouped_amendments::compose_binding(&group,["member-1"]).unwrap(),group.original_scope.binding);
    let mut mutation=original.clone();mutation.id="synthetic-edit-and-cancel".into();mutation.request_id=mutation.id.clone();mutation.fingerprint=mutation.id.clone();mutation.input=prepared.input.clone();mutation.preview=Some(prepared.clone());mutation.status=Status::AwaitingApproval;mutation.submission=None;mutation.effects=None;mutation.last_reconciliation_evidence=None;mutation.approval.as_mut().unwrap().binding_hash=binding_hash(&authorization_binding(&prepared)).unwrap();e.store.lock().unwrap().create_request(&mutation.id,&mutation.request_id,&mutation.fingerprint,&mutation.operation,None,"awaiting_approval",&to_value(&mutation).unwrap(),&now()).unwrap();e.reserve_ordinary_operation(&mut mutation,&prepared, None, None).unwrap();let dispatch=Submission{kind:"synthetic_tx".into(),reference:"synthetic-edit-and-cancel-dispatch".into(),data:json!({"synthetic":true})};e.store.lock().unwrap().persist_submission(&mutation.id,&SubmissionRow{kind:dispatch.kind.clone(),reference:dispatch.reference.clone(),data:dispatch.data.clone()},&now()).unwrap();mutation=e.load_record(&mutation.id).unwrap();
    let cancel=MutationChildProof{child_tag:"member-1".into(),operation_id:original.id.clone(),submission:original.submission.clone().unwrap(),outcome:ChildMutationOutcome::Accepted{successor:None},native_evidence:json!({"bindingReplacementDigest":binding_hash(&json!([])).unwrap(),"nativeAudit":{"cancelId":"synthetic-cancel-b"},"nativeReadback":{"orderId":"synthetic-b","status":"cancelled"}})};let v=grouped_receipt(&mutation,vec![cancel.clone()]);let pending=e.apply_reconciliation(mutation,Reconciliation{status:Status::Pending,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert_eq!(e.amendment_context(&original.id).unwrap().revisions.last().unwrap().scope.intent,original.preview.as_ref().unwrap().intent);assert!(e.store.lock().unwrap().operation_reservations(&pending.id).unwrap().iter().any(|r|r.units=="1000000000000000000"));assert!(e.has_pending_amendment(&original.id).unwrap());drop(e);
    let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let restored=e.load_record(&pending.id).unwrap();let rejected=MutationChildProof{child_tag:"member-0".into(),operation_id:original.id.clone(),submission:original.submission.clone().unwrap(),outcome:ChildMutationOutcome::Rejected{code:"INVALID_ORDER".into()},native_evidence:json!({"error":"synthetic amend rejected"})};let v=grouped_receipt(&restored,vec![cancel,rejected]);let done=e.apply_reconciliation(restored,Reconciliation{status:Status::Failed,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert_eq!(done.status,Status::Failed);assert_eq!(e.load_record(&original.id).unwrap(),original);assert!(!e.has_pending_amendment(&original.id).unwrap());assert_eq!(e.store.lock().unwrap().reservation_count(&done.id).unwrap(),0);
}
